class Program
{
    static void InsertionSort(int[] v)
    {
        for (int i = 1; i < v.Length; i++)
        {
            int atual = v[i];
            int j = i - 1;
            while (j >= 0 && v[j] > atual)
            {
                v[j + 1] = v[j];
                j--;
            }
            v[j + 1] = atual;
        }
    }

    static int BuscaBinaria(int[] v, int alvo)
    {
        int ini = 0, fim = v.Length - 1, achou = -1;
        while (ini <= fim)
        {
            int meio = ini + (fim - ini) / 2;
            if (v[meio] < alvo)
            {
                ini = meio + 1;
            }
            else
            {
                if (v[meio] == alvo) achou = meio;
                fim = meio - 1;
            }
        }
        return achou;
    }

    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        string linha = Console.ReadLine() ?? "";
        int alvo = int.Parse(Console.ReadLine());

        string[] partes = linha.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        int[] v = new int[n];
        for (int i = 0; i < n; i++) v[i] = int.Parse(partes[i]);

        InsertionSort(v);
        Console.WriteLine(n == 0 ? "(vazio)" : string.Join(" ", v));

        int pos = BuscaBinaria(v, alvo);
        Console.WriteLine(pos >= 0 ? $"Posição: {pos}" : "Não encontrado");
    }
}
